int rt_sigqueueinfo(pid_t pid, int sig, siginfo_t __user *uinfo) {
    siginfo_t info;

    // Copy the siginfo structure from user space
    if (copy_from_user(&info, uinfo, sizeof(siginfo_t)))
        return -EFAULT;

    // Check if the signal code is valid
    if (info.si_code >= 0 && info.si_code <= _NSIG_IGN)
        return -EINVAL;

    // Ensure that the caller is not attempting to impersonate another process
    if (pid > 1 && !capable(CAP_KILL))
        return -EPERM;

    // Set the signal number in the siginfo structure
    info.si_signo = sig;

    // Call kill_proc_info to send the signal to the specified process
    return kill_proc_info(sig, &info, pid);
}

int rt_sigqueueinfo(pid_t pid, int sig, siginfo_t __user *uinfo) {
    siginfo_t info;

    if (copy_from_user(&info, uinfo, sizeof(siginfo_t)))
        return -EFAULT;

    if (info.si_code >= 0 && info.si_code < _NSIG)
        return -EINVAL;

    if (pid <= 0)
        return -EPERM;

    info.si_signo = sig;
    return kill_proc_info(sig, &info, pid);
}

#include <linux/signal.h>
#include <linux/errno.h>
#include <linux/uaccess.h>

int rt_sigqueueinfo(pid_t pid, int sig, siginfo_t __user *uinfo) {
    siginfo_t info;

    if (copy_from_user(&info, uinfo, sizeof(siginfo_t)))
        return -EFAULT;

    if (info.si_code >= 0 && info.si_code <= _NSIG_IGN)
        return -EINVAL;

    if (is_impersonating_process(pid))
        return -EPERM;

    info.si_signo = sig;
    return kill_proc_info(sig, &info, pid);
}
